'use strict';
const $=id=>document.getElementById(id);
const TYPES={rewrite:'改写 / 修订','multi-reference':'多参考答案','same-task':'同任务报告',unpaired:'单侧文本',trace:'Agent trace',preference:'偏好标注'};
const FAMILIES={'rewrite-experiment':'改写实验','agentic-technical':'技术文章与 Agent','published-dataset':'公开数据集'};
const ENRICHMENT_GROUPS=[['ai-enrichment-articles','新全文 · Gemini 2.5'],['ai-enrichment-comparison','六篇对照 · Gemini 3.1'],['ai-enrichment-units','新句段与技术片段'],['ai-enrichment-diagnostics','早期诊断']];
const STORE='plainvoice-reviews-v1';
const state={catalog:null,view:"raw",local:false,samples:[],collection:'',offset:0,limit:40,total:0,rows:[],current:null,variant:-1,reviews:{},queryToken:0,recordToken:0};
try{const x=JSON.parse(localStorage.getItem(STORE)||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))state.reviews=x;}catch{}
const text=(id,value)=>{$(id).textContent=value??'';};
const fmt=n=>Number(n||0).toLocaleString('en-US');
const human=v=>typeof v==='string'?v:JSON.stringify(v,null,2);
function el(tag,cls,content){const node=document.createElement(tag);if(cls)node.className=cls;if(content!=null)node.textContent=content;return node;}
function toast(message){text('toast',message);$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3300);}
function reviewKey(r=state.current,variant=state.variant){return r?`${r.id}|${r.content_hash}|${variant}`:'';}
function recordReviewed(r){return Object.values(state.reviews).some(x=>x.id===r.id&&x.content_hash===r.content_hash);}
function updateReviewCount(){text('reviewCount',`${fmt(new Set(Object.values(state.reviews).map(x=>x.id)).size)} 条已评审`);}
async function jsonFetch(url,options){const r=await fetch(url,options);if(!r.ok)throw Error(`请求失败 (${r.status})`);return r.json();}
function showMessage(message){$('detail').hidden=true;$('message').hidden=false;$('message').replaceChildren(typeof message==='string'?document.createTextNode(message):message);}
function publicMessage(){const box=el('div');box.append(el('strong','',`这个数据集的 ${fmt((state.catalog.collections.find(c=>c.id===state.collection)||{}).count)} 条记录已在本机资料库中。`),el('p','','完整文本保留在你的电脑，网上入口展示来源目录和获许可的示例。'));const a=el('a','','打开本机全量资料库 ↗');a.href=state.catalog.local_url||'http://127.0.0.1:8876';box.append(a);showMessage(box);}
function renderCollections(){const container=$('collections');container.replaceChildren();const add=c=>{const b=el('button','collection'+(state.collection===c.id?' active':''));b.append(el('span','',c.title),el('span','count',fmt(c.count)));b.onclick=()=>{state.collection=c.id;state.offset=0;renderCollections();query();};container.append(b);};add({id:'',title:'全部资料',count:state.catalog.total_records});const enriched=new Set(ENRICHMENT_GROUPS.map(([id])=>id));if(state.catalog.collections.some(c=>enriched.has(c.id))){container.append(el('div','family-name','本轮新增 AI 改写'));for(const [id,title] of ENRICHMENT_GROUPS){const c=state.catalog.collections.find(x=>x.id===id);if(c)add({...c,title});}}for(const [family,title] of Object.entries(FAMILIES)){container.append(el('div','family-name',title));for(const c of state.catalog.collections.filter(c=>c.family===family&&!enriched.has(c.id)))add(c);}text('total',fmt(state.catalog.total_records));}
function renderRows(){const box=$('records');box.replaceChildren();if(!state.rows.length)box.append(el('p','empty-list',state.local?'没有符合条件的记录。':'该筛选下没有在线示例。完整记录可在本机打开。'));for(const row of state.rows){const b=el('button','record'+(state.current?.id===row.id?' active':''));b.append(el('div','record-title',row.title));const meta=el('div','record-info');meta.append(el('span','',row.language.toUpperCase()),el('span','',TYPES[row.pair_type]||row.pair_type));if(row.quality_status==='quarantined')meta.append(el('span','quarantine-mark','需处理'));if(recordReviewed(row))meta.append(el('span','reviewed-mark','已评'));b.append(meta);b.onclick=()=>select(row.id);box.append(b);}text('resultCount',`${fmt(state.total)} 条${state.local?'':'在线示例'}`);text('pageInfo',state.total?`${Math.floor(state.offset/state.limit)+1} / ${Math.ceil(state.total/state.limit)}`:'0 / 0');$('prevPage').disabled=!state.offset;$('nextPage').disabled=state.offset+state.limit>=state.total;}
function queryParams(){return{quality_status:state.view==='clean'?$('qualityFilter').value:'',view:state.view,collection:state.collection,language:$('language').value,pair_type:$('pairType').value,q:$('search').value,offset:state.offset,limit:state.limit,review_filter:$('reviewFilter').value,reviews:$('reviewFilter').value?Object.values(state.reviews).map(({id,content_hash,decision})=>({id,content_hash,decision})):[]};}
async function query(){const token=++state.queryToken;const c=state.catalog.collections.find(c=>c.id===state.collection);text('collectionTitle',c?.title||'全部资料');text('collectionNote',state.local?`${fmt(c?.count??state.catalog.total_records)} 条完整记录`:'来源目录 · 全文可在本机查看');text('resultCount','查询中…');try{let result;const p=queryParams();if(state.local)result=await jsonFetch('/api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});else{let rows=state.samples.filter(r=>(!p.collection||r.collection===p.collection)&&(!p.language||r.language===p.language)&&(!p.pair_type||r.pair_type===p.pair_type));if(p.q)rows=rows.filter(r=>[r.title,r.left.text,r.right?.text||'',...(r.alternatives||[]).map(x=>x.text)].join('\n').toLowerCase().includes(p.q.toLowerCase()));if(p.review_filter)rows=rows.filter(r=>{const reviews=Object.values(state.reviews).filter(x=>x.id===r.id&&x.content_hash===r.content_hash);return p.review_filter==='unreviewed'?!reviews.length:p.review_filter==='reviewed'?!!reviews.length:reviews.some(x=>x.decision===p.review_filter);});result={total:rows.length,records:rows.slice(p.offset,p.offset+p.limit)};}if(token!==state.queryToken)return;state.rows=result.records;state.total=result.total;renderRows();if(state.rows.length){if(!state.rows.some(r=>r.id===state.current?.id))await select(state.rows[0].id);}else if(state.local){state.current=null;showMessage('没有符合条件的记录。可以更换数据集、语言或搜索词。');}else{state.current=null;publicMessage();}}catch(e){if(token===state.queryToken)showMessage(`资料查询失败：${e.message}。请确认本机资料库服务正在运行。`);}}
async function select(id){const token=++state.recordToken;try{const r=state.local?await jsonFetch('/api/record?id='+encodeURIComponent(id)+'&view='+state.view):state.samples.find(x=>x.id===id);if(token!==state.recordToken)return;state.current=r;state.variant=-1;renderDetail();renderRows();}catch(e){showMessage(e.message);}}
function sideB(){return state.variant<0?state.current.right:state.current.alternatives[state.variant];}
function renderText(){const r=state.current;if(!r)return;const b=sideB();const blind=$('blind').checked;const label=(side,fallback)=>blind?fallback:`${fallback} · ${side?.label||'未提供'}`;text('leftLabel',label(r.left,'A'));text('rightLabel',label(b,'B'));text('leftText',r.left.text||'（空文本）');text('rightText',b?(b.text||'（空目标：删除）'):'该记录没有配对文本。');text('leftLength',`${fmt(r.left.text.length)} 字符`);text('rightLength',b?`${fmt(b.text.length)} 字符`:'');$('comparison').classList.toggle('single',!b);$('recordSub').hidden=blind;$('recordTitle').textContent=blind?'匿名对照':r.title;$('leftText').scrollTop=0;$('rightText').scrollTop=0;}
function renderDetail(){const r=state.current;$('detail').hidden=false;$('message').hidden=true;const badges=$('recordBadges');badges.replaceChildren(el('span','badge kind',TYPES[r.pair_type]||r.pair_type),el('span','badge',r.language.toUpperCase()));text('recordSub',`${r.collection_title||r.collection} · ${r.id}`);text('contextText',r.context||'没有额外任务说明。');$('contextBox').hidden=!r.context;$('contextBox').open=false;renderText();const alt=$('alternatives');alt.replaceChildren();$('alternativesBox').hidden=!(r.alternatives||[]).length;for(const [i,a] of (r.alternatives||[]).entries()){const d=el('details');d.append(el('summary','',a.label||`参考 ${i+1}`),el('pre','',a.text));const b=el('button','quiet','与 A 对照');b.onclick=()=>{state.variant=i;renderText();loadReview();};d.append(b);alt.append(d);}if((r.alternatives||[]).length){const reset=el('button','quiet','恢复默认 B');reset.onclick=()=>{state.variant=-1;renderText();loadReview();};alt.append(reset);}const info=$('sourceInfo');info.replaceChildren();const p=r.provenance||{};for(const [label,value] of [['来源',p.source_url],['Split',p.split],['文件',p.local_path],['定位',p.record_locator],['许可',p.license],['说明',p.notes]]){if(value==null)continue;const row=el('div','source-row');row.append(el('strong','',label));if(label==='来源'&&typeof value==='string'&&/^https?:\/\//.test(value)){const a=el('a','',value);a.href=value;a.target='_blank';a.rel='noreferrer';row.append(a);}else row.append(el('span','',human(value)));info.append(row);}text('extraText',human(r.extra||{}));renderCleaning();loadReview();}
function loadReview(){const r=state.reviews[reviewKey()]||{};for(const key of ['decision','preference','fidelity','ainess','notes'])$(key).value=r[key]||'';text('saveStatus',r.updated_at?'已保存 · '+new Date(r.updated_at).toLocaleTimeString():'未评审');}
function saveReview(){const r=state.current;if(!r)return;const out={id:r.id,content_hash:r.content_hash,collection:r.collection,right_variant:state.variant,updated_at:new Date().toISOString()};for(const key of ['decision','preference','fidelity','ainess','notes'])out[key]=$(key).value;if(!['decision','preference','fidelity','ainess','notes'].some(k=>out[k]))delete state.reviews[reviewKey()];else state.reviews[reviewKey()]=out;try{localStorage.setItem(STORE,JSON.stringify(state.reviews));text('saveStatus','已自动保存');}catch{text('saveStatus','浏览器存储已满，请导出保存');}updateReviewCount();renderRows();}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function navigate(delta){const idx=state.rows.findIndex(x=>x.id===state.current?.id);if(idx+delta>=0&&idx+delta<state.rows.length)return select(state.rows[idx+delta].id);if(delta>0&&state.offset+state.limit<state.total){state.offset+=state.limit;state.current=null;await query();}else if(delta<0&&state.offset){state.offset-=state.limit;state.current=null;await query();if(state.rows.length)select(state.rows.at(-1).id);}}
$('prevPage').onclick=()=>{state.offset=Math.max(0,state.offset-state.limit);state.current=null;query();};$('nextPage').onclick=()=>{state.offset+=state.limit;state.current=null;query();};$('previous').onclick=()=>navigate(-1);$('next').onclick=()=>navigate(1);$('blind').onchange=renderText;$('textSize').onchange=()=>document.documentElement.style.setProperty('--text-size',$('textSize').value+'px');
for(const id of ['language','pairType','reviewFilter','qualityFilter'])$(id).onchange=()=>{state.offset=0;query();};let searchTimer;$('search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.offset=0;query();},300);};for(const id of ['decision','preference','fidelity','ainess','notes'])$(id).addEventListener('input',saveReview);
let syncing=false;for(const [a,b] of [['leftText','rightText'],['rightText','leftText']])$(a).addEventListener('scroll',()=>{if(!$('sync').checked||syncing)return;syncing=true;const x=$(a),y=$(b);y.scrollTop=x.scrollTop/Math.max(1,x.scrollHeight-x.clientHeight)*(y.scrollHeight-y.clientHeight);requestAnimationFrame(()=>syncing=false);});
$('copyPair').onclick=async()=>{if(!state.current)return;const b=sideB();try{await navigator.clipboard.writeText('A\n'+state.current.left.text+(b?'\n\nB\n'+b.text:''));toast('文本已复制');}catch{toast('当前浏览器无法自动复制，请选中文本复制。');}};
$('export').onclick=()=>download({schema_version:'plainvoice-reviews-1',exported_at:new Date().toISOString(),reviews:Object.values(state.reviews)},'plainvoice-reviews-'+new Date().toISOString().slice(0,10)+'.json');$('importReviews').onclick=()=>$('reviewsFile').click();$('reviewsFile').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>20_000_000)throw Error('评审文件过大');const data=JSON.parse(await file.text());if(data.schema_version!=='plainvoice-reviews-1'||!Array.isArray(data.reviews))throw Error('请选择此 viewer 导出的评审 JSON');let count=0;const imported={...state.reviews};for(const x of data.reviews){if(typeof x.id!=='string'||!/^[a-f0-9]{64}$/.test(x.content_hash)||!Number.isInteger(x.right_variant)||x.right_variant< -1)throw Error('评审格式不完整');for(const key of ['decision','preference','fidelity','ainess','notes'])if(typeof x[key]!=='string')throw Error('评审字段格式错误');const key=reviewKey(x,x.right_variant);const old=imported[key];if(!old||String(x.updated_at)>String(old.updated_at)){imported[key]=x;count++;}}state.reviews=imported;localStorage.setItem(STORE,JSON.stringify(state.reviews));updateReviewCount();if(state.current)loadReview();renderRows();toast(`已导入 ${count} 条评审；不同文本版本会分开保留。`);}catch(e){toast('导入失败：'+e.message);}finally{event.target.value='';}};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='j')navigate(1);if(e.key==='k')navigate(-1);});
async function boot(){updateReviewCount();try{try{state.catalog=await jsonFetch('/api/catalog'+(new URLSearchParams(location.search).has('view')?'?view='+encodeURIComponent(new URLSearchParams(location.search).get('view')):''));state.local=state.catalog.mode==='local';}catch{state.catalog=await jsonFetch('catalog.json');state.local=false;}if(!state.local){state.samples=await jsonFetch(state.catalog.sample_file||'public-samples.json');for(const r of state.samples){if(!r.content_hash){const bytes=new TextEncoder().encode(JSON.stringify(r));const hash=await crypto.subtle.digest('SHA-256',bytes);r.content_hash=[...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}}$('localLink').hidden=false;text('mode','网上目录 + 许可示例');const note=el('div','public-note');note.append(document.createTextNode(`已整理 ${fmt(state.catalog.total_records)} 条记录。此入口提供来源目录与获许可的示例；全量正文在本机资料库。 `));const a=el('a','','打开本机全量 ↗');a.href=state.catalog.local_url;note.append(a);$('main').prepend(note);}else text('mode','本机全量 · 文本不上传');state.view=state.catalog.view||state.catalog.text_view||state.catalog.default_view||'raw';$('textView').value=state.view;$('qualityFilterLabel').hidden=!state.local||state.view!=='clean';$('textView').disabled=!state.local||!(state.catalog.available_views||[]).includes('clean');const params=new URLSearchParams(location.search);const requested=params.get('collection');state.collection=requested!==null&&(requested===''||state.catalog.collections.some(c=>c.id===requested))?requested:(state.catalog.default_collection||'');if(params.has('q'))$('search').value=params.get('q').slice(0,300);if(['en','zh','ja','mixed','unknown'].includes(params.get('language')))$('language').value=params.get('language');renderCollections();await query();if(params.has('id')&&state.local)await select(params.get('id'));}catch(e){showMessage('资料库未能载入：'+e.message);text('mode','连接失败');}}
window.plainvoice={state,query,select,navigate,saveReview};
// Optional page tools share the same actions and state as the visible viewer.
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const tools=[
    {name:'plainvoice_read_current_record',description:'Read the currently selected comparison, source metadata, and local review.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({record:state.current,review:state.reviews[reviewKey()]||null})},
    {name:'plainvoice_open_record',description:'Open a record by its stable ID and update the visible comparison.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.id!=='string'||!input.id.trim())throw Error('A record ID is required');await select(input.id);if(state.current?.id!==input.id)throw Error('Record could not be opened');return{id:state.current.id,title:state.current.title};}},
    {name:'plainvoice_save_current_review',description:'Save an explicit review of the current pair in this browser only. Does not upload or publish data.',inputSchema:{type:'object',properties:{decision:{type:'string',enum:['keep','needs-edit','reject']},notes:{type:'string'}},required:['decision'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!state.current)throw Error('No record selected');if(!['keep','needs-edit','reject'].includes(input?.decision)||('notes'in input&&typeof input.notes!=='string'))throw Error('Invalid review');$('decision').value=input.decision;if(input.notes!==undefined)$('notes').value=input.notes;saveReview();return{id:state.current.id,decision:input.decision,saved_in_browser:true};}}
  ];
  for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

const CLEAN_REASONS={'source_endnotes_missing':'来源快照缺少完整尾注','existing_normalization_requires_review':'前次内容抽取存在待核对项','existing_qa:literal_numbers_missing_or_reformatted':'数字可能遗漏或改换格式','existing_qa:literal_numbers_added_or_reformatted':'数字可能新增或改换格式','existing_qa:normalization_warnings_require_human_review':'内容抽取需要复核','existing_qa:writer_reported_unresolved_or_issues':'生成过程报告了未解决的问题','existing_independent_fidelity_issues':'独立检查发现保真问题','existing_qa:independent_agent_found_fidelity_issues':'独立检查发现保真问题','existing_qa:substantial_compression_check_omissions':'压缩较多，需要核对遗漏','existing_qa:substantial_expansion_check_additions':'扩写较多，需要核对新增内容','pdf_line_end_hyphen_preserved_review_required':'保留了 PDF 换行连字符，需复核','source_math_or_citation_placeholders':'来源含公式或引用占位符','source_reference_placeholders_preserved_review_required':'来源含引用占位符','unmarked_tex_preserved_review_required':'来源公式缺少明确边界，已原样保留','inline_rule_or_fraction_bar_preserved_review_required':'保留了可能是分式的符号行','existing_article_mechanical_review_required':'文章内容清单需要复核',failed_stub:'生成未完成',wrong_language:'输出语言不符',semantic_omission:'已发现内容遗漏',extreme_article_compression:'文章压缩过度，需核对完整性',extreme_compression_review_required:'文章压缩过度，需核对完整性',metadata_mixed_with_substantive_sentence:'网页元数据混在正文句子中，需人工处理',identical_text_no_style_contrast:'两侧相同，没有改写对比信号',existing_semantic_review_flag:'已有语义复核问题',independent_semantic_errors:'独立检查发现语义错误'};
function renderCleaning(){const c=state.current?.extra?.cleaning;const box=$('cleaningStatus');box.hidden=!c;$('cleaningAudit').hidden=!c||!state.local;$('cleaningAudit').open=false;text('cleaningAuditText','');if(!c)return;box.classList.toggle('needs-review',c.status==='quarantined');const title=c.status==='quarantined'?'已隔离 · 暂不进入改写候选导出':c.status==='review_candidate'?'正文已清理 · 改写候选，待人工评审':'清理版本 · 保留原数据集的配对含义';const reasons=[...new Set((c.reasons||[]).map(x=>CLEAN_REASONS[x]||x))];text('cleaningStatus',title+`。${c.changed_sides} 个文本侧有格式变化。`+(reasons.length?' '+reasons.join('；')+'。':'')+(c.status==='archive_only'&&c.warnings?.length?' 来源有 '+c.warnings.length+' 项格式或采集限制，展开清理记录查看。':''));}
$('textView').onchange=async()=>{const id=state.current?.id;state.view=$('textView').value;$('qualityFilterLabel').hidden=state.view!=='clean';$('qualityFilter').value='';++state.queryToken;++state.recordToken;state.current=null;try{state.catalog=await jsonFetch('/api/catalog?view='+state.view);const url=new URL(location.href);url.searchParams.set('view',state.view);if(id)url.searchParams.set('id',id);history.replaceState(null,'',url);await query();if(id)await select(id);toast(state.view==='clean'?'显示清理后正文；评审按此文本版本保存':'显示原始版本；之前的原文评审保留');}catch(e){showMessage(e.message);}};
$('cleaningAudit').ontoggle=async()=>{if(!$('cleaningAudit').open||!state.current)return;const id=state.current.id;const hash=state.current.content_hash;text('cleaningAuditText','载入中…');try{const audit=await jsonFetch('/api/cleaning-audit?id='+encodeURIComponent(id));if(state.current?.content_hash===hash)text('cleaningAuditText',human(audit));}catch(e){if(state.current?.id===id)text('cleaningAuditText',e.message);}};
$('downloadPair').onclick=()=>{if(!state.current)return;const r=state.current;download({id:r.id,source_text:r.left.text,rewrite_text:sideB()?.text??null},'plainvoice-'+state.view+'-'+r.id.replace(/[^a-zA-Z0-9_-]/g,'_')+'.json');};
boot();
